import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any} [intent]
 * @property {any[]} [textContent]
 * @property {any[]} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {Function} emit
 * @property {any} primitives
 */

/**
 * Creates a textured interactive plane node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // root group
  const root = new Group();

  // geometry (1×1 plane, will be scaled by parents if needed)
  const geometry = new PlaneGeometry(1, 1);

  // material – basic unlit, will receive texture async
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  // async texture load
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // silently ignore texture load failures
      });
  }

  // mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // timelines storage
  /** @type {any} */
  let hoverTimeline = null;
  /** @type {any} */
  let clickTimeline = null;

  // userData handlers
  root.userData.handlers = {
    hover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(
        mesh.position,
        { y: mesh.position.y + 0.15, duration: 0.7, ease: 'power3.out' },
        0
      );
    },
    hoverOut: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(
        mesh.position,
        { y: mesh.position.y - 0.15, duration: 0.4, ease: 'power2.out' },
        0
      );
    },
    click: () => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.timeline({
        onComplete: () => {
          ctx.emit('hub-collection.select', {});
        },
      });
      // press‑down effect
      clickTimeline
        .to(
          mesh.scale,
          { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' },
          0
        )
        .to(
          mesh.scale,
          { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out(1.7)' },
          '+=0'
        );
    },
  };

  // cleanup
  root.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();

    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();

    // dispose any children (if any were added later)
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (obj.material.map) obj.material.map.dispose();
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
